import{_ as a,o as e,c as l,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const c=JSON.parse('{"title":"Εγκατάσταση και ανάπτυξη","description":"","frontmatter":{},"headers":[],"relativePath":"el/installation/index.md","filePath":"el/installation/index.md"}'),r={name:"el/installation/index.md"};function d(n,t,o,s,h,p){return e(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="εγκατασταση-και-αναπτυξη" tabindex="-1">Εγκατάσταση και ανάπτυξη <a class="header-anchor" href="#εγκατασταση-και-αναπτυξη" aria-label="Permalink to &quot;Εγκατάσταση και ανάπτυξη&quot;">​</a></h1><p>Ο οδηγός εξηγεί την προετοιμασία εξουσιοδοτημένου περιβάλλοντος TransferBook+, την ένταξη επιχείρησης μεταφορών και την ασφαλή διαχείριση εκδόσεων. Συμπληρώνει τις <a href="/el/system-requirements/">απαιτήσεις συστήματος</a>.</p><div class="warning custom-block"><p class="custom-block-title">Διαθεσιμότητα και ευθύνη</p><p>Οδηγός ετοιμότητας εγκατάστασης, όχι διαθέσιμος installer, υπόσχεση self-hosting ή συμφωνία επιπέδου υπηρεσίας. Λάβετε εγκεκριμένη έκδοση, οδηγίες, ρυθμίσεις πρόσβασης και όρους υποστήριξης από τον πάροχο πριν την ενεργοποίηση. Οι λειτουργίες εξαρτώνται από την αποδοχή έκδοσης, τα δικαιώματα και την ετοιμότητα διασυνδέσεων.</p></div><h2 id="επιλογη-τροπου-εγκαταστασης" tabindex="-1">Επιλογή τρόπου εγκατάστασης <a class="header-anchor" href="#επιλογη-τροπου-εγκαταστασης" aria-label="Permalink to &quot;Επιλογή τρόπου εγκατάστασης&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Τρόπος</th><th>Ευθύνες πελάτη</th><th>Ευθύνες φιλοξενίας</th></tr></thead><tbody><tr><td>Διαχειριζόμενη φιλοξενία, όπου προσφέρεται</td><td>Παροχή επιχειρησιακών ρυθμίσεων, εξουσιοδοτημένων χρηστών και ανατροφοδότησης αποδοχής</td><td>Προετοιμασία και συντήρηση συμφωνημένου περιβάλλοντος, αντιγράφων, παρακολούθησης και εκδόσεων</td></tr><tr><td>Αποκλειστική φιλοξενία, υπό έγκριση</td><td>Συμφωνία χωρητικότητας, πρόσβασης, ασφάλειας και υποστήριξης</td><td>Επαλήθευση υποδομής και επιχειρησιακών διαδικασιών ανά έκδοση</td></tr><tr><td>Αυτοδιαχειριζόμενη εγκατάσταση, αν υποστηρίζεται ρητά</td><td>Ανάθεση σε ειδικευμένη τεχνική ομάδα και αποδοχή συμφωνημένων ευθυνών συντήρησης</td><td>Παροχή μόνο εγκεκριμένου πακέτου και τεκμηριωμένης υποστήριξης</td></tr></tbody></table><p>Οι χρήστες browser δεν εγκαθιστούν τοπικό runtime ή βάση δεδομένων. Μην εγκαθιστάτε demo build ή αυθαίρετο στιγμιότυπο πηγαίου κώδικα ως παραγωγή.</p><h2 id="διαχειριζομενη-ενταξη" tabindex="-1">Διαχειριζόμενη ένταξη <a class="header-anchor" href="#διαχειριζομενη-ενταξη" aria-label="Permalink to &quot;Διαχειριζόμενη ένταξη&quot;">​</a></h2><ol><li>Επιβεβαιώστε εταιρεία, εγκεκριμένο περιβάλλον, έκδοση, διαχειριστή και επαφή υποστήριξης.</li><li>Ρυθμίστε αγορές, ζώνες ώρας, γλώσσες, σημεία παραλαβής/αποβίβασης, στόλο και οδηγούς.</li><li>Ελέγξτε κατηγορίες οχημάτων, τιμές, φόρους, νόμισμα, ναύλους, τύπους κρατήσεων και πολιτικές με την εταιρεία.</li><li>Εκχωρήστε ατομικούς λογαριασμούς και ελάχιστα δικαιώματα· ελέγξτε πρόσβαση και αλλαγές σε κρατήσεις, αναθέσεις και οικονομικά.</li><li>Ενεργοποιήστε μόνο εγκεκριμένα κανάλια και διασυνδέσεις. Διατηρήστε μη εγκεκριμένους παρόχους απενεργοποιημένους.</li><li>Επαληθεύστε αντιπροσωπευτικές κρατήσεις, προσφορές, αναθέσεις και έλεγχο πληρωμών με συνθετικά δεδομένα σε εγκεκριμένο περιβάλλον.</li><li>Λάβετε επιχειρησιακή έγκριση πριν από πραγματικές κρατήσεις. Συμφωνήστε υποστήριξη, συντήρηση και αναφορά συμβάντων.</li></ol><p>Δείτε <a href="/el/plus/markets-and-locations.html">αγορές και τοποθεσίες</a>, <a href="/el/plus/company-and-language-settings.html">ρυθμίσεις εταιρείας</a>, <a href="/el/plus/fleet-management.html">στόλο</a>, <a href="/el/plus/pricing.html">τιμολόγηση</a> και <a href="/el/developers/permissions.html">ρόλους</a>.</p><h2 id="ετοιμοτητα-αποκλειστικης-φιλοξενιας" tabindex="-1">Ετοιμότητα αποκλειστικής φιλοξενίας <a class="header-anchor" href="#ετοιμοτητα-αποκλειστικης-φιλοξενιας" aria-label="Permalink to &quot;Ετοιμότητα αποκλειστικής φιλοξενίας&quot;">​</a></h2><p>Μόνο για εξουσιοδοτημένες τεχνικές ομάδες:</p><ul><li>Επιβεβαιώστε υποστηριζόμενες εκδόσεις runtime και βάσης, σχεδιασμό χωρητικότητας, πακέτα και διαδικασία ακεραιότητας.</li><li>Προετοιμάστε χωριστές ταυτότητες υπηρεσίας και βάσης με ελάχιστα δικαιώματα· αποθηκεύστε μυστικά εκτός δημόσιων αρχείων και Git.</li><li>Ρυθμίστε εγκεκριμένα DNS, HTTPS, reverse proxy, επιτηρούμενες υπηρεσίες, περιορισμένη πρόσβαση βάσης και παρακολούθηση.</li><li>Απομονώστε δεδομένα και διαπιστευτήρια παραγωγής, staging και demo. Μην χρησιμοποιείτε demo ως εγκεκριμένο στόχο εγκατάστασης.</li><li>Ελέγξτε το σχέδιο migrations της έκδοσης και επιβεβαιώστε αντίγραφα και συμβατότητα ανάκτησης πριν από αλλαγή σχήματος.</li><li>Τεκμηριώστε παράθυρο συντήρησης, επηρεαζόμενους χρήστες, υπεύθυνο υποστήριξης, όρους επαναφοράς και διαδικασία αποδοχής.</li></ul><p>Οι <a href="/el/system-requirements/">απαιτήσεις φιλοξενίας</a> είναι βάσεις σχεδιασμού, όχι εγγυημένα όρια χωρητικότητας. Εσωτερικά hostnames, διαδρομές, διαπιστευτήρια και εντολές παραγωγής εξαιρούνται σκόπιμα από τη δημόσια τεκμηρίωση.</p><h2 id="κυκλος-εκδοσεων-και-ενημερωσεων" tabindex="-1">Κύκλος εκδόσεων και ενημερώσεων <a class="header-anchor" href="#κυκλος-εκδοσεων-και-ενημερωσεων" aria-label="Permalink to &quot;Κύκλος εκδόσεων και ενημερώσεων&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Στάδιο</th><th>Απαιτούμενα τεκμήρια</th></tr></thead><tbody><tr><td>Προετοιμασία</td><td>Εγκεκριμένη έκδοση και revision, ακεραιότητα, σημειώσεις και εύρος αλλαγών</td></tr><tr><td>Επικύρωση</td><td>Επιτυχή build και δοκιμές· αποδοχή staging με συνθετικά δεδομένα</td></tr><tr><td>Προστασία</td><td>Επαληθευμένο αντίγραφο, σχέδιο ανάκτησης, συντήρηση και έλεγχος migrations</td></tr><tr><td>Ενεργοποίηση</td><td>Εξουσιοδοτημένη διαδικασία έκδοσης στο προβλεπόμενο περιβάλλον</td></tr><tr><td>Αποδοχή</td><td>Επιτυχείς έλεγχοι υγείας, πρόσβασης, κρατήσεων, αναθέσεων και διασυνδέσεων</td></tr><tr><td>Κλείσιμο</td><td>Καταγραφή έκδοσης, αποτελεσμάτων, εκκρεμών περιορισμών και αναφοράς ανάκτησης</td></tr></tbody></table><p>Δείτε τις <a href="/el/release-notes/">Σημειώσεις εκδόσεων</a>. Η ειδική διαδικασία κάθε έκδοσης υπερισχύει αυτού του οδηγού. Δεν είναι κάθε ενημέρωση αναστρέψιμη: αλλαγή σχήματος ή δεδομένων μπορεί να απαιτεί ξεχωριστή επαναφορά ή διορθωτική αναβάθμιση.</p><h2 id="αντιγραφα-και-ανακαμψη-απο-καταστροφη" tabindex="-1">Αντίγραφα και ανάκαμψη από καταστροφή <a class="header-anchor" href="#αντιγραφα-και-ανακαμψη-απο-καταστροφη" aria-label="Permalink to &quot;Αντίγραφα και ανάκαμψη από καταστροφή&quot;">​</a></h2><p>Συμφωνήστε συχνότητα, διατήρηση, κρυπτογράφηση, αποθήκευση εκτός συστήματος, πρόσβαση ανάκτησης και στόχους ανάκαμψης πριν την έναρξη. Οι στόχοι σημείου και χρόνου ανάκτησης καθορίζονται από τη συμφωνία υπηρεσίας και δοκιμάζονται· δεν υπονοούνται αριθμητικές εγγυήσεις.</p><p>Το σχέδιο καλύπτει βάση, αναγκαίες ρυθμίσεις, πακέτα έκδοσης και περιεχόμενο χρήστη. Διατηρήστε μυστικά σε χωριστή ελεγχόμενη διαδικασία ανάκτησης. Δοκιμάστε επαναφορά σε απομονωμένο περιβάλλον, ελέγξτε εταιρικά όρια και καταγράψτε το αποτέλεσμα. Διατηρήστε τελευταία γνωστή συμβατή έκδοση και ορίστε υπεύθυνο έγκρισης επαναφοράς.</p><p>Σε διακοπή κράτησης ή πληρωμής, επιβεβαιώστε έγκυρη κατάσταση πριν από νέα υποβολή. Αποφύγετε διπλές κρατήσεις και χρεώσεις. Δείτε <a href="/el/developers/idempotency.html">ασφαλή επανάληψη</a> και <a href="/el/tutorials/payment-review.html">έλεγχο πληρωμής</a>.</p><h2 id="λιστα-αποδοχης-εναρξης-λειτουργιας" tabindex="-1">Λίστα αποδοχής έναρξης λειτουργίας <a class="header-anchor" href="#λιστα-αποδοχης-εναρξης-λειτουργιας" aria-label="Permalink to &quot;Λίστα αποδοχής έναρξης λειτουργίας&quot;">​</a></h2><ul><li>Επιβεβαιώστε προβλεπόμενο περιβάλλον και εγκεκριμένη έκδοση.</li><li>Ελέγξτε HTTPS, σύνδεση, αποσύνδεση, λήξη συνεδρίας και όρια ρόλων.</li><li>Ελέγξτε κρατήσεις και προσφορές, συμπεριλαμβανομένης γρήγορης κράτησης χωρίς email.</li><li>Ελέγξτε τιμές, τοποθεσίες, κατηγορίες, ανάθεση οδηγού/οχήματος και πρόγραμμα.</li><li>Δοκιμάστε εγκεκριμένες ειδοποιήσεις, πληρωμές, εξωτερικές αναθέσεις και δημόσια κανάλια μόνο όπου είναι ενεργά.</li><li>Επιβεβαιώστε παρακολούθηση, τεκμήριο επαναφοράς, υπεύθυνο υποστήριξης και εναλλακτικές διαδικασίες.</li><li>Καταγράψτε εκκρεμή προβλήματα και κρατήστε ανενεργές τις ροές που δεν πέρασαν αποδοχή.</li></ul><p>Για εκπαίδευση δείτε <a href="/el/tutorials/">Οδηγούς χρήσης</a>. Για προβλήματα δείτε <a href="/el/help/">Κέντρο βοήθειας</a> και <a href="/el/integrations/activation-and-channels.html">Ετοιμότητα διασυνδέσεων</a>.</p><p><a href="/installation/">English</a></p><p>Πριν την έναρξη δείτε <a href="/el/security-privacy/">Ασφάλεια, ιδιωτικότητα και ΓΚΠΔ</a>.</p>',25)])])}const u=a(r,[["render",d]]);export{c as __pageData,u as default};
